/**
 * How Three black pines (`mitsu-kuromatsu`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/mitsu-kuromatsu";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Three oval sprays turn about the centre. Thirty ruled needles leave each round hub, which has three small paper eyes.","ja":"三つの楕円形の松葉を中心のまわりに配します。小さな白い目を三つ残した丸い根元から、三十本の松葉を定規で伸ばします。"};

export default construction;
export { construction, description };
